/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}
/***********************************************************************************/
var i = 0;
var sqlStatementLen = 0;

/**-------------------------- Log FlexCube Transactions Data --------------------------**/

// save only at the start of the first screen for amend/recreate processes
log.info("finded : "+ tw.local.odcRequest.requestType.value);
log.info("finded 11 : "+tw.local.odcRequest.History.listLength);
//if (tw.local.odcRequest.History.listLength == 0 && (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment+"" || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate+"")) {
i = 0;
log.info("SUCCESS");
while (i < tw.local.odcRequest.FcCollections.selectedTransactions.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	log.info("SUCCESS edLOOP");
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.SQLStatement();
	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatements[sqlStatementLen].sql = "INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_SELECTEDTRANSACTIONS ( " + "REQUESTID, TRANSACTIONID, AMOUNTLINKEDINBPM, AMOUNTINCURRENTREQ,AMOUNTINREQCURRENCY, ISDELETED) " + "VALUES (?, ?, ?, ?, ?,?)";
	log.info("Testde " + sqlStatementLen);
	log.info("Test2ed " + tw.local.odcRequest.FcCollections.transactionIDs[i]);

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.requestID));

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.transactionIDs[i]));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].existAmount));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].amountAllocatedForCurrencyRequest));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FcCollections.selectedTransactions[i].allocatedAmountInRequestCurrency));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter("No"));
	i++;
}
//}
